'use strict';
// TECHNOLOGY REGIME HEADER — tech-command-regime-v1.
//
// A DETERMINISTIC description of the technology environment. Every number here is
// arithmetic over daily candles the app already fetches; no model, no LLM, no
// probability. An LLM may later NARRATE this record, but it can never produce or
// alter a measurement — the one-sentence `novice` line below is generated by rule
// and is the guaranteed fallback.
//
// Missing inputs are reported as missing. A measurement that cannot be computed is
// null with a named reason in `missing[]`; it is never defaulted to zero, and it
// never silently drops out of the classification (the classification records which
// dimensions were unknown).
//
// Pure: candle arrays in, frozen record out. No network, no store, no clock beyond
// the injected `now`.

const REGIME_VERSION = 'tech-command-regime-v1';

// Benchmarks the header reads. TLT is the rate proxy; RSPT is the equal-weight
// technology proxy used against cap-weighted XLK for the concentration read.
const REGIME_TICKERS = Object.freeze(['SPY', 'QQQ', 'XLK', 'RSPT', 'SMH', 'IGV', 'SKYY', 'CIBR', 'TLT']);

// Thresholds — named constants so the classification is auditable, not magic.
const LEAD_PCT = 1.0;            // |tech − SPY| 21-session excess that counts as leadership
const BROAD_PARTICIPATION = 60;  // % of tech names above the 50DMA that counts as broad
const NARROW_PARTICIPATION = 40;
const CONCENTRATION_PCT = 1.5;   // equal-weight minus cap-weight 21-session spread
const VOL_ELEVATED_PCTL = 0.75;  // realized-vol percentile within its own 1y history
const VOL_CALM_PCTL = 0.25;
const LOOKBACK_SHORT = 21;
const LOOKBACK_MED = 63;
const MIN_BREADTH_SAMPLE = 25;   // below this the breadth read is withheld, not estimated

const closesOf = c => (Array.isArray(c) ? c.map(x => (x && Number.isFinite(x.close) ? x.close : null)).filter(v => v != null) : []);
const pct = (a, b) => (Number.isFinite(a) && Number.isFinite(b) && b !== 0 ? ((a - b) / b) * 100 : null);
const r2 = v => (Number.isFinite(v) ? +v.toFixed(2) : null);

/** Trailing simple return (%) over n sessions. */
function retPct(closes, n) {
  if (!closes || closes.length <= n) return null;
  return pct(closes[closes.length - 1], closes[closes.length - 1 - n]);
}

function sma(closes, n) {
  if (!closes || closes.length < n) return null;
  let s = 0;
  for (let i = closes.length - n; i < closes.length; i++) s += closes[i];
  return s / n;
}

function dailyReturns(closes) {
  const out = [];
  for (let i = 1; i < closes.length; i++) {
    if (closes[i - 1] > 0) out.push(closes[i] / closes[i - 1] - 1);
  }
  return out;
}

function stdev(xs) {
  if (!xs || xs.length < 2) return null;
  const m = xs.reduce((a, b) => a + b, 0) / xs.length;
  return Math.sqrt(xs.reduce((s, x) => s + (x - m) ** 2, 0) / (xs.length - 1));
}

function correlation(xs, ys) {
  const n = Math.min(xs.length, ys.length);
  if (n < 20) return null;
  const a = xs.slice(-n), b = ys.slice(-n);
  const ma = a.reduce((s, x) => s + x, 0) / n, mb = b.reduce((s, x) => s + x, 0) / n;
  let cov = 0, va = 0, vb = 0;
  for (let i = 0; i < n; i++) { const p = a[i] - ma, q = b[i] - mb; cov += p * q; va += p * p; vb += q * q; }
  if (!(va > 0) || !(vb > 0)) return null;
  return cov / Math.sqrt(va * vb);
}

/** Percentile rank of the last value within a rolling series of the same statistic. */
function rollingVolPercentile(closes, window = LOOKBACK_SHORT, history = 252) {
  const rets = dailyReturns(closes);
  if (rets.length < window + 30) return { vol: null, percentile: null };
  const vols = [];
  for (let i = window; i <= rets.length; i++) {
    const sd = stdev(rets.slice(i - window, i));
    if (sd != null) vols.push(sd);
  }
  if (!vols.length) return { vol: null, percentile: null };
  const recent = vols.slice(-history);
  const cur = vols[vols.length - 1];
  const below = recent.filter(v => v <= cur).length;
  return { vol: cur * Math.sqrt(252) * 100, percentile: recent.length ? below / recent.length : null };
}

// ── Breadth over member candles ─────────────────────────────────────────────
// `members` is { ticker: candles }. Names without enough history are counted as
// uncovered, never as a failing name.
function breadthOf(members) {
  const entries = Object.entries(members || {});
  let above50 = 0, above200 = 0, with50 = 0, with200 = 0;
  let advancing = 0, declining = 0, unchanged = 0, withChange = 0;
  let newHighs = 0, newLows = 0, withRange = 0;
  const ret21 = [];
  const retSeries = [];
  for (const [, candles] of entries) {
    const c = closesOf(candles);
    if (c.length < 2) continue;
    const last = c[c.length - 1], prev = c[c.length - 2];
    withChange++;
    if (last > prev) advancing++; else if (last < prev) declining++; else unchanged++;
    const s50 = sma(c, 50);
    if (s50 != null) { with50++; if (last > s50) above50++; }
    const s200 = sma(c, 200);
    if (s200 != null) { with200++; if (last > s200) above200++; }
    if (c.length >= LOOKBACK_MED) {
      withRange++;
      const win = c.slice(-LOOKBACK_MED);
      if (last >= Math.max(...win)) newHighs++;
      if (last <= Math.min(...win)) newLows++;
    }
    const r = retPct(c, LOOKBACK_SHORT);
    if (r != null) ret21.push(r);
    const dr = dailyReturns(c.slice(-LOOKBACK_MED - 1));
    if (dr.length >= 40) retSeries.push(dr);
  }
  const sample = withChange;
  const enough = sample >= MIN_BREADTH_SAMPLE;
  return {
    sample,
    sufficient: enough,
    pctAbove50dma: enough && with50 ? r2((above50 / with50) * 100) : null,
    pctAbove200dma: enough && with200 ? r2((above200 / with200) * 100) : null,
    advancing: enough ? advancing : null,
    declining: enough ? declining : null,
    unchanged: enough ? unchanged : null,
    advanceDeclineRatio: enough && declining > 0 ? r2(advancing / declining) : null,
    newHighs63: enough && withRange ? newHighs : null,
    newLows63: enough && withRange ? newLows : null,
    dispersion21: enough ? r2(stdev(ret21)) : null,
    medianRet21: enough && ret21.length ? r2([...ret21].sort((a, b) => a - b)[Math.floor(ret21.length / 2)]) : null,
    averagePairwiseCorrelation: enough ? r2(averageCorrelation(retSeries)) : null,
  };
}

// Bounded average pairwise correlation (a crowding proxy). O(k²) over a capped
// sample so a wide universe cannot blow up the tick.
function averageCorrelation(series, cap = 40) {
  const s = (series || []).slice(0, cap);
  if (s.length < 5) return null;
  let sum = 0, n = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j < s.length; j++) {
      const c = correlation(s[i], s[j]);
      if (c != null) { sum += c; n++; }
    }
  }
  return n ? sum / n : null;
}

// ── The regime record ───────────────────────────────────────────────────────
/**
 * @param {{benchmarks: Object<string, Array>, members?: Object<string, Array>,
 *          now?: Date, sessionInfo?: object}} input
 */
function buildRegime({ benchmarks = {}, members = {}, now = new Date(), sessionInfo = null } = {}) {
  const missing = [];
  const need = t => {
    const c = closesOf(benchmarks[t]);
    if (c.length < LOOKBACK_SHORT + 1) { missing.push(`${t}: insufficient daily history`); return null; }
    return c;
  };
  const spy = need('SPY'), qqq = need('QQQ'), xlk = need('XLK');
  const rspt = need('RSPT'), smh = need('SMH'), igv = need('IGV');
  const skyy = need('SKYY'), cibr = need('CIBR'), tlt = need('TLT');

  const excess = (a, b, n) => {
    const ra = a ? retPct(a, n) : null, rb = b ? retPct(b, n) : null;
    return (ra == null || rb == null) ? null : r2(ra - rb);
  };

  const techVsSpy21 = excess(xlk, spy, LOOKBACK_SHORT);
  const techVsSpy63 = excess(xlk, spy, LOOKBACK_MED);
  const qqqVsSpy21 = excess(qqq, spy, LOOKBACK_SHORT);
  const equalVsCap21 = excess(rspt, xlk, LOOKBACK_SHORT);

  const leadership = [
    ['semiconductors', 'SMH', excess(smh, qqq, LOOKBACK_SHORT)],
    ['software', 'IGV', excess(igv, qqq, LOOKBACK_SHORT)],
    ['cloud', 'SKYY', excess(skyy, qqq, LOOKBACK_SHORT)],
    ['cybersecurity', 'CIBR', excess(cibr, qqq, LOOKBACK_SHORT)],
  ].map(([group, etf, excessPct]) => ({ group, etf, excessVsQqq21: excessPct }))
    .sort((a, b) => (b.excessVsQqq21 ?? -Infinity) - (a.excessVsQqq21 ?? -Infinity));

  const vol = qqq ? rollingVolPercentile(qqq) : { vol: null, percentile: null };
  const rateBeta = (qqq && tlt)
    ? correlation(dailyReturns(qqq).slice(-LOOKBACK_MED), dailyReturns(tlt).slice(-LOOKBACK_MED))
    : null;
  if (rateBeta == null) missing.push('rate sensitivity: QQQ/TLT return history incomplete');

  const breadth = breadthOf(members);
  if (!breadth.sufficient) missing.push(`breadth: only ${breadth.sample} technology names had usable candles (need ${MIN_BREADTH_SAMPLE})`);

  // Intraday VWAP participation needs a full intraday fan-out across the universe,
  // which this page is explicitly forbidden from doing on a read. Reported as
  // unavailable rather than approximated from daily bars.
  missing.push('intraday VWAP participation: requires a universe-wide intraday fan-out; not computed on this surface');

  // ── Deterministic classification ──────────────────────────────────────────
  const leadState = techVsSpy21 == null ? 'unknown'
    : techVsSpy21 >= LEAD_PCT ? 'leading'
      : techVsSpy21 <= -LEAD_PCT ? 'lagging' : 'inline';
  const participationState = breadth.pctAbove50dma == null ? 'unknown'
    : breadth.pctAbove50dma >= BROAD_PARTICIPATION ? 'broad'
      : breadth.pctAbove50dma <= NARROW_PARTICIPATION ? 'narrow' : 'mixed';
  const concentrationState = equalVsCap21 == null ? 'unknown'
    : equalVsCap21 <= -CONCENTRATION_PCT ? 'mega-cap-led'
      : equalVsCap21 >= CONCENTRATION_PCT ? 'equal-weight-led' : 'balanced';
  const volState = vol.percentile == null ? 'unknown'
    : vol.percentile >= VOL_ELEVATED_PCTL ? 'elevated'
      : vol.percentile <= VOL_CALM_PCTL ? 'calm' : 'normal';
  const crowdingState = breadth.averagePairwiseCorrelation == null ? 'unknown'
    : breadth.averagePairwiseCorrelation >= 0.6 ? 'crowded'
      : breadth.averagePairwiseCorrelation <= 0.3 ? 'dispersed' : 'normal';

  const classification = `${leadState}/${participationState}/${concentrationState}`.toUpperCase();
  const knownDims = [leadState, participationState, concentrationState, volState].filter(s => s !== 'unknown').length;

  const topGroup = leadership.find(l => l.excessVsQqq21 != null) || null;
  const laggard = [...leadership].reverse().find(l => l.excessVsQqq21 != null) || null;

  const novice = buildNoviceLine({ leadState, participationState, concentrationState, volState, topGroup, laggard });

  return Object.freeze({
    schema: REGIME_VERSION,
    generatedAt: new Date(now).toISOString(),
    marketSession: sessionInfo ? sessionInfo.marketSession : null,
    sessionDate: sessionInfo ? sessionInfo.etDate : null,
    classification,
    states: Object.freeze({ leadership: leadState, participation: participationState, concentration: concentrationState, volatility: volState, crowding: crowdingState }),
    novice,
    measures: Object.freeze({
      techVsSpy21, techVsSpy63, qqqVsSpy21, equalWeightVsCapWeight21: equalVsCap21,
      leadership: Object.freeze(leadership),
      pctAbove50dma: breadth.pctAbove50dma,
      pctAbove200dma: breadth.pctAbove200dma,
      advancing: breadth.advancing, declining: breadth.declining,
      advanceDeclineRatio: breadth.advanceDeclineRatio,
      newHighs63: breadth.newHighs63, newLows63: breadth.newLows63,
      dispersion21: breadth.dispersion21, medianRet21: breadth.medianRet21,
      averagePairwiseCorrelation: breadth.averagePairwiseCorrelation,
      realizedVolAnnualizedPct: r2(vol.vol),
      realizedVolPercentile1y: vol.percentile == null ? null : r2(vol.percentile),
      rateCorrelationQqqTlt63: r2(rateBeta),
      intradayVwapParticipation: null,
    }),
    coverage: Object.freeze({
      breadthSample: breadth.sample,
      breadthSufficient: breadth.sufficient,
      benchmarksResolved: REGIME_TICKERS.filter(t => closesOf(benchmarks[t]).length >= LOOKBACK_SHORT + 1),
      dimensionsKnown: knownDims,
      dimensionsTotal: 4,
    }),
    missing: Object.freeze(missing),
    thresholds: Object.freeze({ LEAD_PCT, BROAD_PARTICIPATION, NARROW_PARTICIPATION, CONCENTRATION_PCT, VOL_ELEVATED_PCTL, VOL_CALM_PCTL, LOOKBACK_SHORT, LOOKBACK_MED }),
    note: 'Descriptive measurements of the current environment. Not a forecast, not a probability, and not an instruction to trade.',
  });
}

// The guaranteed deterministic one-liner. An LLM narration, if ever added, must
// take THIS record as input and may not contradict it; this stays the fallback.
function buildNoviceLine({ leadState, participationState, concentrationState, volState, topGroup, laggard }) {
  if (leadState === 'unknown' && participationState === 'unknown') {
    return 'Not enough current data to describe the technology environment — treat every board below as low-confidence.';
  }
  const lead = leadState === 'leading' ? 'Technology is leading the market'
    : leadState === 'lagging' ? 'Technology is lagging the market'
      : leadState === 'inline' ? 'Technology is moving roughly in line with the market'
        : 'Technology leadership is unknown';
  const part = participationState === 'broad' ? 'participation is broad'
    : participationState === 'narrow' ? 'participation is narrow'
      : participationState === 'mixed' ? 'participation is mixed'
        : 'participation is unmeasured';
  const conc = concentrationState === 'mega-cap-led' ? ' and concentrated in the largest names'
    : concentrationState === 'equal-weight-led' ? ' and the smaller names are doing the work'
      : '';
  const where = topGroup && topGroup.excessVsQqq21 != null ? `, with ${topGroup.group} strongest${laggard && laggard.group !== topGroup.group ? ` and ${laggard.group} weakest` : ''}` : '';
  const advice = participationState === 'narrow'
    ? ' Favor liquid leaders and demand confirmation in the weaker groups.'
    : participationState === 'broad'
      ? ' Setups outside the mega-caps are more likely to work than usual.'
      : '';
  const volNote = volState === 'elevated' ? ' Volatility is elevated — size smaller.' : '';
  return `${lead}, but ${part}${conc}${where}.${advice}${volNote}`.replace(/\s+/g, ' ').trim();
}

module.exports = {
  REGIME_VERSION, REGIME_TICKERS, buildRegime, breadthOf, buildNoviceLine,
  retPct, sma, dailyReturns, stdev, correlation, rollingVolPercentile, averageCorrelation,
  LEAD_PCT, BROAD_PARTICIPATION, NARROW_PARTICIPATION, CONCENTRATION_PCT, MIN_BREADTH_SAMPLE,
};
